  BER_decode_strip_tags(*p_td.ber, p_tlv, L_form, stripped_tlv);
  TTCN_EncDec_ErrorContext ec("While decoding ENUMERATED type @ITS-Container.AltitudeConfidence: ");
  int tmp_mfr;
