p_buf.PER_put_bit(field_outerhardShoulderStatus_present);
boolean field_drivingLaneStatus_present = field_drivingLaneStatus.is_present();
p_buf.PER_put_bit(field_drivingLaneStatus_present);
if (field_innerhardShoulderStatus_present) field_innerhardShoulderStatus.PER_encode(ClosedLanes_innerhardShoulderStatus_descr_, p_buf, p_options);
if (field_outerhardShoulderStatus_present) field_outerhardShoulderStatus.PER_encode(ClosedLanes_outerhardShoulderStatus_descr_, p_buf, p_options);
