void ClosedLanes::PER_decode(const TTCN_Typedescriptor_t& p_td, TTCN_Buffer& p_buf, int p_options)
{
clean_up();
boolean ext_bit = p_buf.PER_get_bit();
boolean field_innerhardShoulderStatus_present = p_buf.PER_get_bit();
boolean field_outerhardShoulderStatus_present = p_buf.PER_get_bit();
boolean field_drivingLaneStatus_present = p_buf.PER_get_bit();
if (field_innerhardShoulderStatus_present) field_innerhardShoulderStatus.PER_decode(ClosedLanes_innerhardShoulderStatus_descr_, p_buf, p_options);
else field_innerhardShoulderStatus = OMIT_VALUE;
if (field_outerhardShoulderStatus_present) field_outerhardShoulderStatus.PER_decode(ClosedLanes_outerhardShoulderStatus_descr_, p_buf, p_options);
else field_outerhardShoulderStatus = OMIT_VALUE;
if (field_drivingLaneStatus_present) field_drivingLaneStatus.PER_decode(ClosedLanes_drivingLaneStatus_descr_, p_buf, p_options);
else field_drivingLaneStatus = OMIT_VALUE;
Vector<boolean> ext_presences;
if (ext_bit) {
INTEGER length_;
int normally_small_length = TRUE;
int mul_16k;
do {
mul_16k = length_.PER_decode_length(p_buf, p_options, normally_small_length);
if (mul_16k > 0) normally_small_length = FALSE;
for (int i = 0; i < length_; ++i) {
ext_presences.push_back(p_buf.PER_get_bit());
}
}
while (mul_16k > 0);
}
int nof_decoded_ext_adds = ext_presences.size();
for (int i = 0; i < nof_decoded_ext_adds; ++i) {
if (ext_presences[i]) PER_skip_opentype(p_buf, p_options);
}
}

