ASN_BER_TLV_t* VehicleIdentification::BER_encode_TLV(const TTCN_Typedescriptor_t& p_td, unsigned p_coding) const
{
  if (!is_bound()) TTCN_EncDec_ErrorContext::error(TTCN_EncDec::ET_UNBOUND, "Encoding an unbound value.");
  BER_chk_descr(p_td);
  ASN_BER_TLV_t *new_tlv=ASN_BER_TLV_t::construct(NULL);
  TTCN_EncDec_ErrorContext ec_0("Component '");
  TTCN_EncDec_ErrorContext ec_1;
  ec_1.set_msg("wMInumber': ");
  new_tlv->add_TLV(field_wMInumber.BER_encode_TLV(VehicleIdentification_wMInumber_descr_, p_coding));
  ec_1.set_msg("vDS': ");
  new_tlv->add_TLV(field_vDS.BER_encode_TLV(VehicleIdentification_vDS_descr_, p_coding));
  new_tlv=ASN_BER_V2TLV(new_tlv, p_td, p_coding);
  return new_tlv;
}

boolean VehicleIdentification::BER_decode_TLV(const TTCN_Typedescriptor_t& p_td, const ASN_BER_TLV_t& p_tlv, unsigned L_form)
{
  BER_chk_descr(p_td);
  ASN_BER_TLV_t stripped_tlv;
  BER_decode_strip_tags(*p_td.ber, p_tlv, L_form, stripped_tlv);
  TTCN_EncDec_ErrorContext ec_0("While decoding '@ITS-Container.VehicleIdentification' type: ");
  stripped_tlv.chk_constructed_flag(TRUE);
  size_t V_pos=0;
  ASN_BER_TLV_t tmp_tlv;
  boolean tlv_present=FALSE;
  {
    TTCN_EncDec_ErrorContext ec_1("Component '");
    TTCN_EncDec_ErrorContext ec_2;
    ec_2.set_msg("wMInumber': ");
    if(!tlv_present) tlv_present=BER_decode_constdTLV_next(stripped_tlv, V_pos, L_form, tmp_tlv);
    if(!tlv_present) field_wMInumber=OMIT_VALUE;
    else {
      field_wMInumber.BER_decode_TLV(VehicleIdentification_wMInumber_descr_, tmp_tlv, L_form);
      if(field_wMInumber.ispresent()) tlv_present=FALSE;
    }
    ec_2.set_msg("vDS': ");
    if(!tlv_present) tlv_present=BER_decode_constdTLV_next(stripped_tlv, V_pos, L_form, tmp_tlv);
    if(!tlv_present) field_vDS=OMIT_VALUE;
    else {
      field_vDS.BER_decode_TLV(VehicleIdentification_vDS_descr_, tmp_tlv, L_form);
      if(field_vDS.ispresent()) tlv_present=FALSE;
    }
  }
  BER_decode_constdTLV_end(stripped_tlv, V_pos, L_form, tmp_tlv, tlv_present);
  return TRUE;
}

int VehicleIdentification::JSON_encode(const TTCN_Typedescriptor_t&, JSON_Tokenizer& p_tok, boolean p_parent_is_map) const
{
  if (!is_bound()) {
    TTCN_EncDec_ErrorContext::error(TTCN_EncDec::ET_UNBOUND,
      "Encoding an unbound value of type @ITS-Container.VehicleIdentification.");
    return -1;
  }

  int enc_len = p_tok.put_next_token(JSON_TOKEN_OBJECT_START, NULL);

  if (field_wMInumber.is_present())
  {
    enc_len += p_tok.put_next_token(JSON_TOKEN_NAME, "wMInumber");
    enc_len += field_wMInumber.JSON_encode(VehicleIdentification_wMInumber_descr_, p_tok, FALSE);
  }

  if (field_vDS.is_present())
  {
    enc_len += p_tok.put_next_token(JSON_TOKEN_NAME, "vDS");
    enc_len += field_vDS.JSON_encode(VehicleIdentification_vDS_descr_, p_tok, FALSE);
  }

  enc_len += p_tok.put_next_token(JSON_TOKEN_OBJECT_END, NULL);
  return enc_len;
}

int VehicleIdentification::JSON_decode(const TTCN_Typedescriptor_t& p_td, JSON_Tokenizer& p_tok, boolean p_silent, boolean p_parent_is_map, int)
{
  if (p_td.json->default_value.type == JD_STANDARD && 0 == p_tok.get_buffer_length()) {
    *this = *static_cast<const VehicleIdentification*>(p_td.json->default_value.val);
    return 0;
  }
  json_token_t j_token = JSON_TOKEN_NONE;
  size_t dec_len = p_tok.get_next_token(&j_token, NULL, NULL);
  if (JSON_TOKEN_ERROR == j_token) {
    JSON_ERROR(TTCN_EncDec::ET_INVAL_MSG, JSON_DEC_BAD_TOKEN_ERROR, "");
    return JSON_ERROR_FATAL;
  }
  else if (JSON_TOKEN_OBJECT_START != j_token) {
    return JSON_ERROR_INVALID_TOKEN;
  }
  boolean wMInumber_found = FALSE;
  boolean vDS_found = FALSE;

  while (TRUE) {
    char* fld_name = 0;
    size_t name_len = 0;
    size_t buf_pos = p_tok.get_buf_pos();
    dec_len += p_tok.get_next_token(&j_token, &fld_name, &name_len);
    if (JSON_TOKEN_ERROR == j_token) {
      JSON_ERROR(TTCN_EncDec::ET_INVAL_MSG, JSON_DEC_NAME_TOKEN_ERROR);
      return JSON_ERROR_FATAL;
    }
    else if (JSON_TOKEN_NAME != j_token) {
      p_tok.set_buf_pos(buf_pos);
      break;
    }
    else {
      if (9 == name_len && 0 == strncmp(fld_name, "wMInumber", name_len)) {
        wMInumber_found = TRUE;
         int ret_val = field_wMInumber.JSON_decode(VehicleIdentification_wMInumber_descr_, p_tok, p_silent, FALSE);
         if (0 > ret_val) {
           if (JSON_ERROR_INVALID_TOKEN == ret_val) {
             JSON_ERROR(TTCN_EncDec::ET_INVAL_MSG, JSON_DEC_FIELD_TOKEN_ERROR, 9, "wMInumber");
           }
           return JSON_ERROR_FATAL;
         }
         dec_len += (size_t)ret_val;
      }
      else if (3 == name_len && 0 == strncmp(fld_name, "vDS", name_len)) {
        vDS_found = TRUE;
         int ret_val = field_vDS.JSON_decode(VehicleIdentification_vDS_descr_, p_tok, p_silent, FALSE);
         if (0 > ret_val) {
           if (JSON_ERROR_INVALID_TOKEN == ret_val) {
             JSON_ERROR(TTCN_EncDec::ET_INVAL_MSG, JSON_DEC_FIELD_TOKEN_ERROR, 3, "vDS");
           }
           return JSON_ERROR_FATAL;
         }
         dec_len += (size_t)ret_val;
      }
      else {
        if (p_silent) {
          return JSON_ERROR_INVALID_TOKEN;
        }
        JSON_ERROR(TTCN_EncDec::ET_INVAL_MSG, JSON_DEC_INVALID_NAME_ERROR, (int)name_len, fld_name);
        dec_len += p_tok.get_next_token(&j_token, NULL, NULL);
        if (JSON_TOKEN_NUMBER != j_token && JSON_TOKEN_STRING != j_token &&
            JSON_TOKEN_LITERAL_TRUE != j_token && JSON_TOKEN_LITERAL_FALSE != j_token &&
            JSON_TOKEN_LITERAL_NULL != j_token) {
          JSON_ERROR(TTCN_EncDec::ET_INVAL_MSG, JSON_DEC_FIELD_TOKEN_ERROR, (int)name_len, fld_name);
          return JSON_ERROR_FATAL;
        }
      }
    }
  }

  dec_len += p_tok.get_next_token(&j_token, NULL, NULL);
  if (JSON_TOKEN_OBJECT_END != j_token) {
    JSON_ERROR(TTCN_EncDec::ET_INVAL_MSG, JSON_DEC_OBJECT_END_TOKEN_ERROR, "");
    return JSON_ERROR_FATAL;
  }

  if (!wMInumber_found) {
    field_wMInumber = OMIT_VALUE;
  }
  if (!vDS_found) {
    field_vDS = OMIT_VALUE;
  }
  
  return (int)dec_len;
}

int VehicleIdentification::OER_encode(const TTCN_Typedescriptor_t&, TTCN_Buffer& p_buf) const
{
  if (!is_bound()) {
  TTCN_EncDec_ErrorContext::error(TTCN_EncDec::ET_UNBOUND,
    "Encoding an unbound record value.");
  return -1;
  }
  char c = 0;
  if (field_wMInumber.is_present()) {
    c |= 64;
  }
  if (field_vDS.is_present()) {
    c |= 32;
  }
  p_buf.put_c(c);
  if (field_wMInumber.is_present())
    field_wMInumber.OER_encode(VehicleIdentification_wMInumber_descr_, p_buf);
  if (field_vDS.is_present())
    field_vDS.OER_encode(VehicleIdentification_vDS_descr_, p_buf);
  return 0;
}

int VehicleIdentification::OER_decode(const TTCN_Typedescriptor_t&, TTCN_Buffer& p_buf, OER_struct& p_oer)
{
  const unsigned char* uc = p_buf.get_read_data();
  p_buf.increase_pos(1);
  boolean has_extension = FALSE;
  if (uc[0] & 0x80) {
    has_extension = TRUE;
  }
  if (uc[0] & 64)
    field_wMInumber.OER_decode(VehicleIdentification_wMInumber_descr_, p_buf, p_oer);
 else
    field_wMInumber = OMIT_VALUE;
  if (uc[0] & 32)
    field_vDS.OER_decode(VehicleIdentification_vDS_descr_, p_buf, p_oer);
 else
    field_vDS = OMIT_VALUE;
  if (has_extension) {
    size_t bytes = decode_oer_length(p_buf, FALSE);
    uc = p_buf.get_read_data();
    p_buf.increase_pos(bytes);
    uc++;
  }
  return 0;
}

void VehicleIdentification::PER_encode(const TTCN_Typedescriptor_t& p_td, TTCN_Buffer& p_buf, int p_options) const
{
if (!is_bound()) {
TTCN_EncDec_ErrorContext::error(TTCN_EncDec::ET_UNBOUND, "Encoding an unbound SEQUENCE value.");
return;
}
boolean ext_bit = FALSE;
p_buf.PER_put_bit(ext_bit);
boolean field_wMInumber_present = field_wMInumber.is_present();
p_buf.PER_put_bit(field_wMInumber_present);
boolean field_vDS_present = field_vDS.is_present();
p_buf.PER_put_bit(field_vDS_present);
if (field_wMInumber_present) field_wMInumber.PER_encode(VehicleIdentification_wMInumber_descr_, p_buf, p_options);
if (field_vDS_present) field_vDS.PER_encode(VehicleIdentification_vDS_descr_, p_buf, p_options);
}

void VehicleIdentification::PER_decode(const TTCN_Typedescriptor_t& p_td, TTCN_Buffer& p_buf, int p_options)
{
clean_up();
boolean ext_bit = p_buf.PER_get_bit();
boolean field_wMInumber_present = p_buf.PER_get_bit();
boolean field_vDS_present = p_buf.PER_get_bit();
if (field_wMInumber_present) field_wMInumber.PER_decode(VehicleIdentification_wMInumber_descr_, p_buf, p_options);
else field_wMInumber = OMIT_VALUE;
if (field_vDS_present) field_vDS.PER_decode(VehicleIdentification_vDS_descr_, p_buf, p_options);
else field_vDS = OMIT_VALUE;
Vector<boolean> ext_presences;
if (ext_bit) {
INTEGER length_;
int normally_small_length = TRUE;
int mul_16k;
do {
mul_16k = length_.PER_decode_length(p_buf, p_options, normally_small_length);
if (mul_16k > 0) normally_small_length = FALSE;
for (int i = 0; i < length_; ++i) {
ext_presences.push_back(p_buf.PER_get_bit());
}
}
while (mul_16k > 0);
}
int nof_decoded_ext_adds = ext_presences.size();
for (int i = 0; i < nof_decoded_ext_adds; ++i) {
if (ext_presences[i]) PER_skip_opentype(p_buf, p_options);
}
}

