void ProtectedZoneType::PER_decode(const TTCN_Typedescriptor_t&, TTCN_Buffer& p_buf, int p_options)
{
INTEGER dec_val;
boolean ext_bit = p_buf.PER_get_bit();
if (ext_bit) dec_val.PER_decode_normally_small(p_buf, p_options);
else enum_value = permanentCenDsrcTolling;
int dec_int = ext_bit ? (int)dec_val : 0;
if (ext_bit) switch (dec_int) {
case 0: enum_value = temporaryCenDsrcTolling; break;
default: enum_value = UNBOUND_VALUE; break;
}
}

